import json

class Document:
    def __init__(self, id, data):
        self.id = id
        self.data = data

    def to_dict(self):
        return {'id': self.id, **self.data}

    @staticmethod
    def from_dict(doc_dict):
        doc_id = doc_dict.pop('id', None)
        return Document(doc_id, doc_dict)

class QueryResult:
    def __init__(self, documents):
        self.documents = documents

    def to_json(self):
        return json.dumps([doc.to_dict() for doc in self.documents], indent=2)

from database_client import get_container_client
from database_models import Document
import os

def conditional_update(document_id, new_data, etag=None):
    database_name = os.environ.get("AZURE_COSMOS_DATABASE")
    container_name = os.environ.get("AZURE_COSMOS_CONTAINER")
    container = get_container_client(database_name, container_name)

    try:
        # Read the current document to get the latest etag
        current_document = container.read_item(item=document_id, partition_key=document_id)

        if etag and current_document['_etag'] != etag:
            return {'success': False, 'message': 'ETag mismatch, document has been modified.'}

        # Prepare the updated document
        updated_document = {
            'id': document_id,
            **current_document, # Keep existing fields
            **new_data # Overwrite with new data
        }

        # Perform the upsert with the etag for conditional update
        # Cosmos DB will implicitly use the _etag for optimistic concurrency
        # when doing an upsert on an existing item that includes the _etag field.
        result = container.upsert_item(body=updated_document)
        return {'success': True, 'document': Document.from_dict(result)}
    except Exception as e:
        print(f"Error performing conditional update: {e}")
        return {'success': False, 'message': str(e)}

from openai import AzureOpenAI
import os

def record_summary(text_content):
    client = AzureOpenAI(
        api_key=os.environ.get("AZURE_OPENAI_API_KEY"),  
        api_version=os.environ.get("AZURE_OPENAI_API_VERSION"),
        azure_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
    )

    # Assuming a deployment name for the model, e.g., "text-davinci-003" or a chat model
    deployment_name = os.environ.get("AZURE_OPENAI_DEPLOYMENT_NAME")

    try:
        # For older models like davinci, use client.completions.create
        # For chat models like gpt-35-turbo, use client.chat.completions.create
        # This example assumes a chat-based model.
        response = client.chat.completions.create(
            model=deployment_name,
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes text."},
                {"role": "user", "content": f"Summarize the following text: {text_content}"}
            ]
        )
        return {'summary': response.choices[0].message.content.strip()}
    except Exception as e:
        print(f"Error summarizing text with Azure OpenAI: {e}")
        return {'summary': None, 'error': str(e)}

from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions
from azure.core.credentials import AzureKeyCredential
import os

def record_text_safety(text_content):
    endpoint = os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.environ.get("AZURE_CONTENT_SAFETY_KEY")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    try:
        request = AnalyzeTextOptions(text=text_content)
        response = client.analyze_text(request)

        # Extracting results for different categories
        safety_results = {
            "hate": response.hate_result.severity if response.hate_result else 0,
            "self_harm": response.self_harm_result.severity if response.self_harm_result else 0,
            "sexual": response.sexual_result.severity if response.sexual_result else 0,
            "violence": response.violence_result.severity if response.violence_result else 0,
        }
        return {'safety_scores': safety_results}
    except Exception as e:
        print(f"Error checking text safety with Azure Content Safety: {e}")
        return {'safety_scores': None, 'error': str(e)}

import requests
import uuid
import os

def record_translate(text_content, to_language='en', from_language='auto'):
    endpoint = os.environ.get("AZURE_TRANSLATOR_ENDPOINT")
    key = os.environ.get("AZURE_TRANSLATOR_KEY")
    region = os.environ.get("AZURE_TRANSLATOR_REGION") # e.g., "global", "westus2"

    path = '/translate'
    constructed_url = endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': region,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    params = {
        'api-version': '3.0',
        'to': to_language,
    }
    if from_language != 'auto':
        params['from'] = from_language

    body = [{'text': text_content}]

    try:
        request = requests.post(constructed_url, params=params, headers=headers, json=body)
        response = request.json()

        if request.status_code == 200 and response and len(response) > 0 and 'translations' in response[0]:
            translated_text = response[0]['translations'][0]['text']
            detected_language = response[0].get('detectedLanguage', {}).get('language')
            return {'translated_text': translated_text, 'detected_language': detected_language}
        else:
            return {'translated_text': None, 'error': response}

    except Exception as e:
        print(f"Error translating text with Azure Translator: {e}")
        return {'translated_text': None, 'error': str(e)}

from azure.storage.blob import BlobServiceClient
import os

def record_export_archive(file_content, file_name, container_name="document-archives"):
    connect_str = os.environ.get("AZURE_STORAGE_CONNECTION_STRING")
    if not connect_str:
        return {'success': False, 'message': 'Azure Storage connection string not found.'}

    blob_service_client = BlobServiceClient.from_connection_string(connect_str)

    try:
        # Create a blob client for the specific blob
        blob_client = blob_service_client.get_blob_client(container=container_name, blob=file_name)

        # Upload the file content
        blob_client.upload_blob(file_content, overwrite=True)

        return {'success': True, 'blob_url': blob_client.url}
    except Exception as e:
        print(f"Error archiving document to Azure Blob Storage: {e}")
        return {'success': False, 'message': str(e)}
